"""Write a reviewable reading; final record and snapshot freeze are separate."""
import json,re
from pathlib import Path
H=Path(__file__).resolve().parents[1];R=H/'results'
read=lambda p:json.loads(p.read_text())
def main():
 s=read(R/'report-summary.json');factor=read(R/'closure-factorial.json');v=read(R/'all-channel-verification.json');freeze=read(H/'preparation/reduced-window-freeze.json');edges=read(H/'preparation/window-edges.json');historic=read(R/'historical-comparison.json')['rows']
 def fmt(x):return f'{x:,.6f}'
 lines=['# Plant-closure execution reading',f"The native study completed {s['unique_cases']:,} distinct cases. {s['fully_satisfied']:,} satisfy all eighteen modeled predicates; {s['satisfaction_counts']['old-ten']:,} satisfy the current old-ten view and {s['satisfaction_counts']['round1-fourteen']:,} the current fourteen view. The historical physical tuples, exclusions, and both loop assumptions are retained. These counts describe sampled model satisfaction; they do not certify an engineered plant.",'## Closure attribution','All eight controls use the current package and corrected operating-heating basis. All-held reproduces the stated direct accounting terms; it is not a rerun of the historical installed-heating model.','| Anchor | Complete corners | All-held primary LCOE | All-live primary LCOE | Change | Interaction residual |','|---|---|---|---|---|---|']
 for x in factor:
  if x['complete_factorial']:
   corners={tuple(c['modes']):c for c in x['corners']};e=x['effects']['lcoe'];lines.append(f"| {x['anchor']} | 8/8 | {fmt(corners[(0,0,0)]['lcoe'])} | {fmt(corners[(1,1,1)]['lcoe'])} | {fmt(e['all_live_minus_all_held'])} | {fmt(e['interaction_residual'])} |")
  else:lines.append(f"| {x['anchor']} | Unavailable; retained algebraic exclusion | — | — | — | — |")
 lines+=['Dollar values in this table are $/MWh. Single effects are measured from all-held. The interaction residual is the all-live change minus the sum of the three single effects. `results/closure-factorial.json` retains every corner, qualified-verdict membership, both LCOEs, the loop→cycle→calendar path, pair interactions and the triple interaction. `results/lcoe-bridges.json` decomposes each path step into capital, annual cost and energy terms, with a checked residual.','## Reduced native verification of the historical window','| Arm | Eligible correlations | Excluded correlations | Distinct native cases | Current old-ten / fourteen / eighteen satisfied | Best full-current sampled primary LCOE |','|---|---|---|---|---|---|']
 for arm in s['arms']:
  for a in arm['power_levels']:
   best=a['best_full_current_sample'];lines.append(f"| {arm['arm_id']} at {a['installed_power_MW']:g} MW installed | {a['correlation_status_counts'].get('eligible',0):,} | {a['correlation_status_counts'].get('excluded',0):,} | {a['unique_cases']:,} | {a['satisfaction_counts']['old-ten']:,} / {a['satisfaction_counts']['round1-fourteen']:,} / {a['fully_satisfied_unique_cases']:,} | {fmt(best['lcoe']) if best else 'None'} |")
 lines+=['All sustainment readings use the native stored-energy basis W_th = 1.5 p_avg V, expressed in MJ, and the source-shaped helium/electron profiles. Coupling efficiency stays 1.0; the inherited source-efficiency values are explicit in the retained inputs. Operating heat follows signed demand, while the installed reserve supplies the procurement/capacity control. Availability scales accumulated energy and fuel, not online loop or exhaust duty.','Cycle temperatures are turbine-inlet Celsius values derived from the Kelvin loop outlet minus the held 20 K approach. The source fits deliberately use ln(T2_C + 273) with their declared domains and zero delta correction. Current window arms hold total radiation at 0.90 and use the 9.5 MW/m² reference transport case; other transport/radiation values belong only to their named sensitivities.','Physical fuel recovery remains 0.99 and the achieved TBR remains held at 1.074. Required breeding and its margin are reported separately from the authored held-floor predicate. Vacuum speed is conditional on the explicit exhaust pressure in results/package-inputs.json. These inputs supply no inventory, startup or installed-equipment evidence.']
 lines+=['The best values are sampled minima at each stated installed wallplug power and under the named assumptions. They are not global optima. `results/historical-comparison.json` keeps selected historical IDs and original ten-predicate verdicts beside current old-ten, intermediate-fourteen and full-eighteen views. Historical cost deltas include upstream revision changes; the factorial is the separate closure attribution. `results/historical-window-summary.json` gives the historical ten-predicate and current per-set best points at each installed-power level, with predicate transitions joined by case ID. Fixed-loop and capacity-sized results are separate assumptions. Loop sizing has no pump, pipe or IHX cost optimum.','Every old excluded row is reconsidered and keeps its historical exclusion identity. Algebraic exclusions never count as evaluated violations. `preparation/correlation.json` retains the complete oracle-screened history, reasons and tracebacks; the reduced native correlation is in `preparation/reduced-correlation.json`. `results/correlation.json` supplies native candidate IDs for eligible rows. `results/native-points.csv` is unique by candidate; `results/points.csv` repeats the same evidence by arm correlation.','## Window edges']
 for e in edges:
  title=f"{e['arm_id']} / {e['historical_arm']} / {e['installed_power_MW']:g} MW installed"
  if not e['edges']:lines.append(f"- {title}: no full-eighteen feasible scan anchor; no boundary claim.")
  else:lines.append(f"- {title}: anchor {e['anchor_label']}; "+'; '.join(f"{x['axis'].split('__')[-1]} {x['side']} {x['value']:g}: {x['status']}" for x in e['edges'])+'.')
 lines+=['Edges use actual inherited low/high coordinates and the declared loop rule. All are engineered extents. An uncaught edge remains uncaught. A predicate failure at an endpoint is sampled edge evidence, not a continuous boundary solution. The four owner-approved sensitivities make no feasibility-boundary claim.','## Constraint outcomes','| Qualified constraint | Source local identity | Satisfied cases | Violated cases |','|---|---|---|---|']
 for cid,c in s['constraint_counts'].items():lines.append(f"| `{cid}` | `{c['source_local_identity']}` | {c.get('satisfied',0):,} | {c.get('violated',0):,} |")
 lines+=['Exact per-case predicate outcomes are in both CSV exports. There is no indeterminate result hidden in these counts. Every arithmetic failure or rejected proposal remains outside the completed-case count.','## Sensitivity interpretation','Availability control, outage duration, residual unplanned downtime and burn fraction retain the owner-approved ranges and missing resistance findings. Calendar output is conditional on the deterministic schedule and the selected unplanned fraction. Burn and vacuum throughput do not supply fuel inventory, startup stock, processing capacity or an installed vacuum train.','The transport comparison uses the source’s two alternative target-load cases at fixed radiation. The radiation sweep is engineered. Source-low results are restricted to the chosen anchors; no source-low full-window minimum is reported. The radius-scaled divertor shadow is diagnostic and never substitutes for the fixed-target predicate.','The Rankine and sCO2 controls use the complete sourced fit definitions. Temperature points outside the fit domain remain diagnostics with their predicates. The fit domain is not a materials qualification. Hydraulic loss/flow cases test the representative circuit equations, with source/calibration transfer limits retained.','All 30 per-axis accounts are in `results/axis-accounts.json`, including exact values, cost ranges and every violated-constraint count at each value. Aggregate bins contain coordinated variations and are not causal derivatives. Explicit paired families and closure corners provide the controlled comparisons.','## Calendar and financial evidence','`results/derived-event-tables.json` reports dates derived independently from stored operands. Dates are not native scalar outputs. Computed-calendar events use strict restart before the horizon; held-calendar events retain the periodic convention. `results/calendar-transect.json` retains every inherited minor-radius transect row, including both sides of observed replacement-count steps.','Both LCOEs use finite discounted sums at held discount 0.07, inflation 0.02, eight construction years and thirty operational years. The finance ledgers retain capital, annual cost and energy for every case. This tests the declared numerical convention and does not certify zero-rate, equal-rate, multimodule or cross-concept normalization behavior.','## Verification',f"The all-case verifier passes for {v['cases']:,} cases: all 141 independent oracle channels, all eighteen rederived predicates, seventeen additional scalar identities and the physical/calendar/finance ledgers. Maximum deviations and each check count are retained in `results/all-channel-verification.json`. The generic verifier independently reruns a sample stratified by observed verdict combinations; its exact sample and result are in `results/verification_summary.json`.",'The seventeen extra outputs remain outside the shared oracle interface. Study-local equations provide the explicitly described checks; no adapter capability was expanded. The 147 globally unsupported input overrides remain a global limitation, while all changing inputs in this study are mapped. Shared literal thresholds and source assumptions are not independently validated by arithmetic agreement.','The prior quarantined-file hashing incident remains a historical process violation. The corrected permitted-surface guard and this study’s scoped operations do not erase it or establish historical clean-room compliance. No scientific-use allegation is inferred. Native audits for earlier items retain their actual scope; implementation/integration is not relabeled an independent item audit.','## Remaining decisions','Fresh final review, record-only administration, the goal disposition checkpoint and consolidated non-author grading follow this executor reading. Final packet/demo acceptance, source adoption, comparison-contract changes and reveal remain with their existing authority.']
 oracle=read(R/'oracle-window-summary.json')
 extra=['## Coverage after the owner-directed reduction','The primary native comparison uses 371 risk-selected cases. The exhaustive attempt was stopped at the owner’s request after 2,525 completed cases. Its unchanged store and interruption log remain supporting evidence; the first 844 completed cases passed independent checks. That ordered prefix is not a random or representative sample. It is excluded from all primary native counts.','The complete independent oracle scan retains every historical row and exclusion. Full-window counts and case-id flips below are oracle results, not exhaustive native results. Every candidate minimum under the three predicate views, all 73 observed oracle verdict patterns, all comparison blocks, all 84 edge checks and the complete calendar transect are covered by the reduced native selection. Agreement on this selected set does not prove native equivalence at unexecuted grid points.','| Oracle window | Eligible / excluded correlations | Old-ten / fourteen / eighteen satisfied | Full-eighteen candidate minimum ($/MWh) |','|---|---|---|---|']
 for g in oracle['groups']:
  c=g['oracle_status_counts'];a=g['oracle_satisfaction_counts'];b=g['oracle_minima']['current-eighteen'];extra.append(f"| {g['arm_id']} / {g['historical_arm']} / {g['installed_power_MW']:g} MW | {c.get('eligible',0)} / {c.get('excluded',0)} | {a['old-ten']} / {a['round1-fourteen']} / {a['current-eighteen']} | {fmt(b['lcoe']) if b else 'None'} |")
 extra+=['`results/oracle-historical-comparison.json` retains full-scan case-id flips and cost values. `results/oracle-window-summary.json` retains per-set candidate coordinates and aspect ratios. Native results and full-oracle results remain separate evidence layers. The selected minima are verified model points within an engineered scanned window; no global optimum or buildable-plant claim follows.']
 lines[2:2]=extra
 (H/'execution-reading.md').write_text(re.sub(r'(?m)(^\|[^\n]*\|)\n\n(?=\|)',r'\1\n','\n\n'.join(lines))+'\n')
 print('Reviewable execution reading written; no record or snapshot rewritten')
if __name__=='__main__':main()
